mapper.select:
select * from ( select
CASE WHEN a.mid_plan_qty = 0 THEN NULL WHEN a.mid_plan_qty != 0 THEN ( c.MID_FINISH_QTY / a.mid_plan_qty ) END AS mid_finish_rate, CASE WHEN a.night_plan_qty = 0 THEN NULL WHEN a.night_plan_qty != 0 THEN ( c.NIGHT_FINISH_QTY / a.night_plan_qty ) END AS night_finish_rate, CASE WHEN a.day_plan_qty = 0 THEN NULL WHEN a.day_plan_qty != 0 THEN ( c.DAY_FINISH_QTY / a.day_plan_qty ) END AS day_finish_rate, (IFNULL(MID_PLAN_QTY, 0) + IFNULL(NIGHT_PLAN_QTY, 0) + IFNULL(DAY_PLAN_QTY, 0)) as daily_total_qty, b.MONTH_PLAN_QTY as month_plan, b.MONTH_REMAIN_QTY as month_plan_os, c.MID_FINISH_QTY as MID_FINISH_QTY, c.NIGHT_FINISH_QTY as NIGHT_FINISH_QTY, c.DAY_FINISH_QTY as DAY_FINISH_QTY, d.DIMENSION, e.COLOR_TYPE, e.COLOR_CODE, log.change_machine, log.change_mid_plan, log.change_night_plan, log.change_day_plan from t_gsq_schedule_result a LEFT JOIN ( select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY from T_GSQ_MONTH_PLAN_SURPLUS where YEAR=#{year,jdbcType=VARCHAR} and MONTH= #{month,jdbcType=VARCHAR} and del_flag = '0' ) b on a.STEEL_RING_CODE=b.MATERIAL_CODE LEFT JOIN T_GSQ_STEEL_TYPE_COLOR e ON a.STEEL_TYPE = e.STEEL_TYPE AND e.STATUS = '0' AND e.DEL_FLAG = '0' LEFT JOIN T_GSQ_DAY_FINISH_QTY c ON a.order_no = c.order_no and c.del_flag = '0' LEFT JOIN ( SELECT BEAD_CODE, max(DIMENSION) DIMENSION FROM T_PRODUCT_CONSTRUCTION_INFO group by BEAD_CODE ) d on a.STEEL_RING_CODE = d.BEAD_CODE LEFT JOIN (/*调度员操作日志，判断调度员是否有做“转机台”或“调量”操作*/ SELECT schedule_id, max(IF(BEFORE_MACHINE_ID = AFTER_MACHINE_ID,0,1)) change_machine, max(IF(BEFORE_MID_PLAN = AFTER_MID_PLAN,0,1)) change_mid_plan, max(IF(BEFORE_NIGHT_PLAN = AFTER_NIGHT_PLAN,0,1)) change_night_plan, max(IF(BEFORE_DAY_PLAN = AFTER_DAY_PLAN,0,1)) change_day_plan FROM T_GSQ_DISPATCHER_LOG where schedule_date = #{scheduleDate} group by schedule_id ) log ON a.id = log.schedule_id where a.del_flag = '0' and a.schedule_date = #{scheduleDate} and INSTR(a.steel_type, #{steelType}) > 0 and INSTR(a.steel_ring_code, #{steelRingCode,jdbcType=VARCHAR}) > 0 and a.production_status = #{productionStatus} and instr(concat(',',a.machine_id,','), concat(',',#{machineId},','))>0 and a.IS_RELEASE = #{isRelease} and a.id in #{scheduleId} order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,a.RANK, d.DIMENSION ) t
order by ${orderStr}

select count(1)
from t_schedule_publish_record
where procedure_code = #{procedureCode,jdbcType=VARCHAR}
  and schedule_date = #{scheduleDate,jdbcType=DATE}
  and publish_status = '1'
  and del_flag = '0'

select count(1) from t_gsq_schedule_result
where del_flag = '0'
and schedule_date = #{scheduleDate}
and steel_ring_code = #{steelRingCode}
and machine_id = #{machineId}
and id != #{id}

select count(1) from t_gsq_schedule_result
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

mapper.update:
update t_gsq_schedule_result
set IS_RELEASE = #{isRelease, jdbcType=VARCHAR}
,PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where del_flag = 0 and schedule_date = #{scheduleDate,jdbcType=DATE}
  and (IS_RELEASE = 3 or IS_RELEASE = 4)

update t_schedule_publish_record
set publish_status = #{publishStatus, jdbcType=VARCHAR},
    update_by = #{updateBy},
    update_time = #{updateTime}
where del_flag = 0 and procedure_code = #{procedureCode,jdbcType=VARCHAR}
  and schedule_date = #{scheduleDate,jdbcType=DATE}

UPDATE t_schedule_publish_record
   SET PUBLISH_STATUS = #{status}
 WHERE data_version = #{dataVersion}
   AND del_flag = 0

update t_gsq_schedule_result set IS_RELEASE = #{status}
, PUBLISH_SUCCESS_COUNT = PUBLISH_SUCCESS_COUNT + 1, NEWEST_PUBLISH_TIME = now()
where id in

    #{id}

update t_gsq_schedule_result set del_flag = NULL
where id in

    #{id}

mapper.select:
SELECT schedule_date, SUM(mid_plan_qty) as day_plan_qty, SUM(night_plan_qty) as night_plan_qty, SUM(day_plan_qty) as next_day_plan_qty, SUM(stock_qty) as stock_qty FROM t_gsq_schedule_result WHERE schedule_date = #{scheduleDate} and INSTR(steel_type, #{steelType}) > 0 and INSTR(steel_ring_code, #{steelRingCode,jdbcType=VARCHAR}) > 0
and production_status = #{productionStatus} and instr(concat(',',machine_id,','), concat(',',#{machineId},','))>0
and IS_RELEASE = #{isRelease}

SELECT SUM(night_plan_qty) as night_plan_qty FROM t_gsq_schedule_result WHERE schedule_date = DATE_SUB(#{scheduleDate}, INTERVAL 1 DAY) and INSTR(steel_type, #{steelType}) > 0 and INSTR(steel_ring_code, #{steelRingCode,jdbcType=VARCHAR}) > 0
and production_status = #{productionStatus} and instr(concat(',',machine_id,','), concat(',',#{machineId},','))>0
and IS_RELEASE = #{isRelease}
